expression_rule:
@ref-param[force-one-to-one=true]this.DTVIGOR = (SELECT MAX(T2.DTVIGOR)
                 FROM TGFTAB T2
                 WHERE T2.CODTAB = this.CODTAB)

@ref-param[force-one-to-one=true]this.DHALTER= (SELECT MAX(TOP2.DHALTER) FROM TGFTOP TOP2 
WHERE TOP2.CODTIPOPER = this.CODTIPOPER AND this.ATIVO = TOP2.ATIVO 
AND this.TIPMOV = TOP2.TIPMOV AND  TOP2.ATIVO = 'S' AND TOP2.TIPMOV ='F')

@ref-param[force-one-to-one=true] HistoricoWorkCenterAtividade.DHALOC = (SELECT MAX(HWXA.DHALOC) FROM TPRHWXA HWXA WHERE HWXA.CODWCP = HistoricoWorkCenterAtividade.CODWCP
AND HWXA.IDIPROC = HistoricoWorkCenterAtividade.IDIPROC
AND HWXA.IDIATV = HistoricoWorkCenterAtividade.IDIATV)

@ref-param[merge-to-find=true]
(EXISTS (SELECT NULL FROM VIMADM WHERE ADMIMOVEL = this.IMVCODIGO) 
AND (this.IMVESTAGIO IN ('DI','LV', 'CP')))

@ref-param[merge-to-find=true]
@form-filter[EXISTS (
SELECT 1 FROM TIMIMP IMP 
WHERE IMP.IMPPROPRIETARIO = this.CODPARC 
AND EXISTS ( SELECT 1 FROM TIMADM ADM WHERE ADM.ADMNUCONTRATO = IMP.IMPCONTRATO 
AND EXISTS(SELECT 1 FROM TIMLOC LOC WHERE LOC.LOCCONTRATOADM = ADM.ADMNUCONTRATO AND LOC.LOCCODIGO = form.DTLCONTRATOLOC)))]

@ref-param[merge-to-find=true]
@form-filter[this.IMVESTAGIO <> (CASE WHEN  ${user.name}.GET_TSIPAR_USUARIO_LOGICO('TIMOCULTBAAP')='N' THEN 'ZZ' ELSE 'BA' END)

AND 
(
	(
		(
			(
				(
					(CASE WHEN this.IMVULTADMVENDA IS NULL THEN 'N' ELSE 'S' END) =  ${user.name}.EHCORRETORVENDA() or  ${user.name}.EHCORRETORVENDA() = 'S'
				) 
				AND ((CASE WHEN this.IMVULTADM IS NULL THEN 'N' ELSE 'S' END) =  ${user.name}.EHCORRETORLOC() or ${user.name}.EHCORRETORLOC() = 'S')
			) OR 
			(
				(CASE WHEN this.IMVULTADMVENDA IS NULL THEN 'N' ELSE 'S' END) = 'S' AND (CASE WHEN this.IMVULTADM IS NULL THEN 'N' ELSE 'S' END) = 'S'
			)
		)
	AND ( ${user.name}.EHCORRETORVENDA() = 'S' OR  ${user.name}.EHCORRETORLOC() = 'S') OR (this.IMVULTADM IS NULL AND this.IMVULTADMVENDA IS NULL))
	OR  ${user.name}.GET_TSIPAR_USUARIO_LOGICO('TIMCTRLPROD')='N'
)]

                @form-filter[this.CODCGP =  form.CODCGP AND  this.CODFRM = form.CODFRM AND this.CODCFR IN (
    SELECT CFR.CODCFR
    FROM ZDBCFR CFR
    WHERE CFR.CODCGP = form.CODCGP AND CFR.CODCFR <> form.CODCFR AND CFR.CODFRM = form.CODFRM
    AND CFR.CODPFR = (SELECT CODPFR FROM ZDBCFR WHERE CODCGP = form.CODCGP AND CODCFR = form.CODCFR AND CODFRM = form.CODFRM)
)]
@ref-param[sorted-by=CODCFR]
